// BANK (s512 a1): shape 0.953, 950/940 B. Remaining: zero constant held in EDX from the out-record clear to the loop head (retail ECX, then test ecx,ecx), lea ebx scheduled before the clear, found-branch dir.y product not hoisted (fxch), final do-loop aligned with lea esp,[esp]. The searching flag only un-rotates the main loop; see attempt_support/20261031-path-computepointonpath-3fd7d0.md
// Retail 0x003FD7D0, 940 bytes, thiscall RET 0x10.  BFME's Path cursor walk:
// the matched AIUpdateInterface::needToRotate (0x00271390) and the locomotor
// path resync (0x001B7200) call it through ILT 0x00008A9E, which the
// symbols.csv pin names Path::computePointOnPath with this argument list.
// Path layout (+0x04 m_path, +0x08 m_pathTail, +0x10 cursor node, +0x14
// cursor position, +0x20 cursor distance) is the one PathAdvanceCachedPoint.cpp
// (0x003FDC70) witnesses.  The Object argument is unused, as in retail.

#include <math.h>

typedef bool Bool;
typedef float Real;
typedef int Int;

enum PathfindLayerEnum
{
	LAYER_INVALID = 0,
	LAYER_GROUND = 1
};

struct Coord2D
{
	Real x;
	Real y;

	void normalize();
};

struct Coord3D
{
	Real x;
	Real y;
	Real z;

	Coord3D() {}
	Coord3D(const Coord3D &that) { x = that.x; y = that.y; z = that.z; }

	Real length() const { return (Real)sqrt(x * x + y * y + z * z); }
	void sub(const Coord3D *that) { x -= that->x; y -= that->y; z -= that->z; }
};

class Object;
class Rva001B7200Locomotor;

class Locomotor
{
public:
	Real getPreferredHeight() const;
};

// 36-byte out record (Locomotor_rva001B7200.cpp).
struct Rva001B7200PathPoint
{
	Real m_real00;
	Coord3D m_coord04;
	Coord3D m_coord10;
	PathfindLayerEnum m_layer;
	Int m_int20;
};

class PathNode
{
public:
	const PathNode *getNextOptimized(Coord2D *dir, Real *dist) const;

	PathNode *m_next;
	PathNode *m_previous;
	PathNode *m_nextOptimized;
	Coord3D m_position;
	PathfindLayerEnum m_layer;
	Bool m_canOptimize;
	Int m_waypointID;
};

struct BlockRva003D5C60BlockAssign
{
	Coord3D m_position;
};

class Rva003D5C60BlockAssign
{
public:
	void set(const BlockRva003D5C60BlockAssign &value);
};

class AI
{
public:
	char m_pad00[0xc];
	Rva003D5C60BlockAssign *m_pathfinder;
};
extern AI *TheAI;

struct Rva003FD7D0Portal
{
	char m_pad00[0x60];
	Int m_type;
};

#define RVA003FD7D0_SLOT(n) virtual void slot##n() = 0;

class TerrainLogic
{
public:
	RVA003FD7D0_SLOT(00) RVA003FD7D0_SLOT(01) RVA003FD7D0_SLOT(02) RVA003FD7D0_SLOT(03)
	RVA003FD7D0_SLOT(04) RVA003FD7D0_SLOT(05) RVA003FD7D0_SLOT(06) RVA003FD7D0_SLOT(07)
	RVA003FD7D0_SLOT(08) RVA003FD7D0_SLOT(09) RVA003FD7D0_SLOT(10) RVA003FD7D0_SLOT(11)
	RVA003FD7D0_SLOT(12) RVA003FD7D0_SLOT(13) RVA003FD7D0_SLOT(14) RVA003FD7D0_SLOT(15)
	RVA003FD7D0_SLOT(16) RVA003FD7D0_SLOT(17) RVA003FD7D0_SLOT(18) RVA003FD7D0_SLOT(19)
	RVA003FD7D0_SLOT(20) RVA003FD7D0_SLOT(21) RVA003FD7D0_SLOT(22) RVA003FD7D0_SLOT(23)
	RVA003FD7D0_SLOT(24) RVA003FD7D0_SLOT(25) RVA003FD7D0_SLOT(26) RVA003FD7D0_SLOT(27)
	RVA003FD7D0_SLOT(28) RVA003FD7D0_SLOT(29) RVA003FD7D0_SLOT(30) RVA003FD7D0_SLOT(31)
	virtual Rva003FD7D0Portal *getWaypointPortal(Int id) = 0;
};
extern TerrainLogic *TheTerrainLogic;

class Path
{
public:
	void computePointOnPath(Object *object, Rva001B7200Locomotor *locomotor,
		Rva001B7200PathPoint *out, Bool update);

private:
	unsigned char m_head[4];
	PathNode *m_path;
	PathNode *m_pathTail;
	Int m_isOptimized;
	const PathNode *m_cursor;
	Coord3D m_cursorPosition;
	Real m_cursorDistance;
};

// ?computePointOnPath@Path@@QAEXPAVObject@@PAVRva001B7200Locomotor@@PAURva001B7200PathPoint@@_N@Z
void Path::computePointOnPath(Object *object, Rva001B7200Locomotor *locomotor,
	Rva001B7200PathPoint *out, Bool update)
{
	Real distance = 40.0f;
	if (locomotor)
	{
		distance = ((Locomotor *)locomotor)->getPreferredHeight();
		if (distance <= 0.1f)
		{
			distance = 0.1f;
			if (!update)
				distance = 1.0f;
		}
	}

	out->m_layer = LAYER_GROUND;
	out->m_coord04.x = 0.0f;
	out->m_coord04.y = 0.0f;
	out->m_coord04.z = 0.0f;
	Coord3D *outPosition = &out->m_coord04;
	out->m_real00 = 0.0f;
	out->m_int20 = 0x7fffffff;
	out->m_coord10.x = 0.0f;
	out->m_coord10.y = 0.0f;
	out->m_coord10.z = 0.0f;

	if (m_path == 0)
		return;

	if (m_cursor == 0)
	{
		m_cursor = m_path;
		m_cursorDistance = 0.0f;
		m_cursorPosition = m_path->m_position;
	}

	Coord3D *cursorPosition = &m_cursorPosition;
	Real along = m_cursorDistance;
	Coord3D position = *cursorPosition;
	const PathNode *node = m_cursor;
	Real segmentLength = 0.00001f;
	Coord2D dir;
	Bool searching = true;
	while (searching && node)
	{
		const PathNode *next = node->getNextOptimized(&dir, &segmentLength);
		if (next == 0)
			break;
		Real scale = 1.0f;
		if (next->m_waypointID != 0x7fffffff)
		{
			Rva003FD7D0Portal *portal = TheTerrainLogic->getWaypointPortal(next->m_waypointID);
			if (portal)
			{
				if (portal->m_type == 1)
				{
					Real remaining = segmentLength - along;
					if (remaining > distance)
						distance = remaining - 0.001;
				}
				if (portal->m_type == 3)
				{
					scale = segmentLength / ((Real)fabs(next->m_position.z - node->m_position.z) + 1.0f);
					if (scale > 1.0f)
						scale = 1.0f;
					else if (scale < 0.5f)
						scale *= 0.85f;
				}
			}
		}
		Real remaining = segmentLength - along;
		if (remaining > scale * distance)
		{
			distance = scale * distance;
			*outPosition = position;
			dir.normalize();
			outPosition->x += dir.x * distance;
			out->m_coord04.y += dir.y * distance;
			out->m_coord04.z += (next->m_position.z - node->m_position.z) * (distance / segmentLength);
			out->m_real00 = segmentLength - along;
			out->m_coord10 = next->m_position;
			along += distance;
			out->m_int20 = next->m_waypointID;
			out->m_layer = next->m_layer;
			goto found;
		}
		distance -= remaining / scale;
		node = next;
		position = node->m_position;
		along = 0.0f;
	}

	if (m_pathTail)
	{
		*outPosition = m_pathTail->m_position;
		out->m_coord10 = m_pathTail->m_position;
		out->m_int20 = m_pathTail->m_waypointID;
		out->m_layer = m_pathTail->m_layer;
		node = m_pathTail;
		out->m_real00 = 0.0f;
		Coord3D delta(*outPosition);
		along = 0.0f;
		delta.sub(cursorPosition);
		out->m_real00 = delta.length();
	}

found:
	if (update)
	{
		m_cursor = node;
		m_cursorDistance = along;
		*cursorPosition = *outPosition;
		TheAI->m_pathfinder->set(*(const BlockRva003D5C60BlockAssign *)outPosition);
	}

	if (node)
	{
		const PathNode *walk = node->m_nextOptimized;
		Real length = 0.0f;
		while (walk)
		{
			out->m_real00 += length;
			walk = walk->getNextOptimized(&dir, &length);
		}
	}
}
